# The error indicates some liked songs may not be in the user's library, so remove_song_from_library may fail.
# We will unlike all liked songs first, then try to remove from library only if it does not error.
# To avoid stopping on error, we will catch exceptions and continue.

for song in liked_songs:
    song_id = song["song_id"]
    try:
        apis.spotify.unlike_song(song_id=song_id, access_token=access_token)
    except Exception:
        pass
    try:
        apis.spotify.remove_song_from_library(song_id=song_id, access_token=access_token)
    except Exception:
        pass

# The error indicates some liked songs may not be in the user's library, so we should handle exceptions and continue.
for song in liked_songs:
    song_id = song["song_id"]
    try:
        apis.spotify.remove_song_from_library(song_id=song_id, access_token=access_token)
    except Exception:
        # Ignore if song is not in library
        pass
    try:
        apis.spotify.unlike_song(song_id=song_id, access_token=access_token)
    except Exception:
        # Ignore if song is already unliked or other errors
        pass

# The error indicates some liked songs are not in the user's library, so removing them from library fails.
# To avoid this, first get the list of songs in the user's library, then only remove those liked songs that are also in the library.

library_songs = []
page_index = 0
page_limit = 20

while True:
    library_songs_page = apis.spotify.show_song_library(access_token=access_token, page_index=page_index, page_limit=page_limit)
    if not library_songs_page:
        break
    library_songs.extend(library_songs_page)
    if len(library_songs_page) < page_limit:
        break
    page_index += 1

library_song_ids = {song["song_id"] for song in library_songs}

# Now unlike all liked songs and remove only those that are in the library
for song in all_liked_songs:
    song_id = song["song_id"]
    apis.spotify.unlike_song(song_id=song_id, access_token=access_token)
    if song_id in library_song_ids:
        apis.spotify.remove_song_from_library(song_id=song_id, access_token=access_token)

